import os
import torch


class Config:
    # ==========================================
    # Global Seeds & Hardware
    # ==========================================
    SEED = 42
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # ==========================================
    # Data Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata Parquet Files (Generated by previous steps)
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Working Directory for Caching & Checkpoints
    # Using 'idea_40' as requested for directory safety
    WORKING_DIR = "./working/idea_40"

    # Submission Directory
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # ==========================================
    # Data Processing & Feature Engineering
    # ==========================================
    # Target Column Name
    TARGET_COL = "Cover_Type"
    ID_COL = "Id"

    # Number of output classes (Cover_Type 1-7)
    # We will likely map 1-7 to 0-6 internally or use 7 output logits
    NUM_CLASSES = 7

    # ==========================================
    # Model Architecture Hyperparameters
    # ==========================================
    # Branch 1: Low-Rank Factorized DCN
    DCN_RANK = 4  # Rank for Matrix decomposition U * V^T
    DCN_LAYERS = 3  # Asymmetric depth (shallower than backbone)

    # Branch 2: ResNet Backbone
    RESNET_BLOCKS = 5  # Scaled depth
    DROPOUT = 0.2  # Regularization within blocks

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 4096
    EPOCHS = 60

    # Optimizer (AdamW)
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Scheduler (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.1
    SCHEDULER_PATIENCE = 5

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 10

    # Annealed Deep Supervision
    # Loss = Primary + lambda_t * Auxiliary
    AUX_LOSS_WEIGHT_START = 0.3
    AUX_LOSS_WEIGHT_END = 0.0

    # System Settings
    NUM_WORKERS = 4  # Adjust based on vCPU count (12 available)
    PIN_MEMORY = True

    @classmethod
    def print_config(cls):
        """Prints the current configuration."""
        print("=" * 30)
        print("CONFIGURATION")
        print("=" * 30)
        for attr in dir(cls):
            if not attr.startswith("__") and not callable(getattr(cls, attr)):
                print(f"{attr}: {getattr(cls, attr)}")
        print("=" * 30)
